//! The enclave runtime behind the two ECALLs of `Enclave.edl`.
//!
//! [`Runtime`] holds the per-instance state: the identity key `EK`, the
//! protocol endpoint and the application. Its methods are platform-agnostic
//! (attester and RNG are parameters), so the state machine is tested on the
//! build host. The `ecall_*` functions are the thin `unsafe` layer that the
//! `extern "C"` entry points generated by [`crate::export_enclave!`] call
//! with the pointers from the edger8r bridge (`Enclave_t.c`).
//!
//! ECALL ABI (unchanged from the blueprint, `docs/PROTOCOL.md` §2):
//!
//! ```c
//! uint32_t     enclave_create_report(const sgx_target_info_t* p_qe3_target,
//!                                    sgx_report_t* p_report);
//! sgx_status_t enclave_message(const uint8_t* p_data /* [in, 4096] */,
//!                              uint32_t data_size,
//!                              uint8_t* p_response   /* [in, out, 4096] */,
//!                              uint32_t* p_response_size /* [out] */);
//! ```

use alloc::vec::Vec;
use core::cell::UnsafeCell;
use core::fmt;
use core::sync::atomic::{AtomicBool, Ordering};

use sgx_ra_core::attestation::Attester;
use sgx_ra_core::handshake::IdentityKey;
use sgx_ra_core::rng::{Rng, RngError};
use sgx_ra_core::session::{EnclaveEndpoint, EndpointError};
use sgx_ra_core::sgx::report::{REPORT_LEN, TARGET_INFO_LEN};
use sgx_ra_core::sgx::{Report, TargetInfo};
use sgx_ra_core::wire::MAX_PAYLOAD;

use crate::app::{AppError, EnclaveApp, SessionContext};
use crate::ffi;
use crate::platform::{SgxAttester, SgxRng, SgxStatus};

/// Why an ECALL failed. Only the [`EcallError::status`] code reaches the
/// host; protocol details stay inside the enclave.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum EcallError {
    /// A pointer or length from the host is invalid.
    InvalidParameter,
    /// `enclave_message` before `enclave_create_report`.
    NotAttested,
    /// The runtime is already executing an ECALL (re-entry or a second
    /// thread).
    Busy,
    /// The RNG failed.
    Rng(RngError),
    /// Report creation failed.
    Attestation(SgxStatus),
    /// The protocol endpoint rejected the message; the session is closed.
    Protocol(EndpointError<AppError>),
}

impl EcallError {
    /// The `sgx_status_t` returned to the host.
    pub fn status(&self) -> SgxStatus {
        match self {
            Self::InvalidParameter => SgxStatus::INVALID_PARAMETER,
            Self::NotAttested => SgxStatus::INVALID_STATE,
            Self::Busy => SgxStatus::INVALID_STATE,
            Self::Rng(_) => SgxStatus::UNEXPECTED,
            Self::Attestation(status) => *status,
            // One code for every protocol failure: the host learns that the
            // session ended, not why.
            Self::Protocol(_) => SgxStatus::UNEXPECTED,
        }
    }
}

impl fmt::Display for EcallError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidParameter => f.write_str("invalid ECALL parameter"),
            Self::NotAttested => f.write_str("enclave_message before enclave_create_report"),
            Self::Busy => f.write_str("enclave runtime busy"),
            Self::Rng(e) => e.fmt(f),
            Self::Attestation(status) => write!(f, "report creation failed: {status}"),
            Self::Protocol(e) => e.fmt(f),
        }
    }
}

impl core::error::Error for EcallError {}

struct State<A> {
    endpoint: EnclaveEndpoint,
    app: A,
}

/// Per-instance enclave state, stored in a `static` by
/// [`crate::export_enclave!`].
///
/// The state is created by the first `enclave_create_report`: a fresh
/// identity key from the enclave RNG, then [`EnclaveApp::init`]. Calls are
/// serialised by a flag; a concurrent or re-entrant call fails with
/// [`EcallError::Busy`] instead of blocking (the blueprint configuration has
/// a single TCS, so this never happens with a well-behaved host).
pub struct Runtime<A> {
    busy: AtomicBool,
    state: UnsafeCell<Option<State<A>>>,
}

// SAFETY: `state` is only accessed while `busy` is held (acquire/release),
// so at most one thread touches it at a time; `A: Send` lets the state move
// between the threads that enter the enclave.
unsafe impl<A: Send> Sync for Runtime<A> {}

/// Releases the busy flag on drop.
struct BusyGuard<'a>(&'a AtomicBool);

impl Drop for BusyGuard<'_> {
    fn drop(&mut self) {
        self.0.store(false, Ordering::Release);
    }
}

impl<A: EnclaveApp> Runtime<A> {
    /// An empty runtime (no key, no application yet).
    pub const fn new() -> Self {
        Self {
            busy: AtomicBool::new(false),
            state: UnsafeCell::new(None),
        }
    }

    fn with_state<R>(
        &self,
        f: impl FnOnce(&mut Option<State<A>>) -> Result<R, EcallError>,
    ) -> Result<R, EcallError> {
        if self
            .busy
            .compare_exchange(false, true, Ordering::Acquire, Ordering::Relaxed)
            .is_err()
        {
            return Err(EcallError::Busy);
        }
        let _guard = BusyGuard(&self.busy);
        // SAFETY: the busy flag gives this call exclusive access to `state`
        // until `_guard` is dropped.
        f(unsafe { &mut *self.state.get() })
    }

    /// Whether the identity key exists (a report has been requested).
    pub fn is_initialized(&self) -> Result<bool, EcallError> {
        self.with_state(|state| Ok(state.is_some()))
    }

    /// The public half of the identity key, once it exists.
    pub fn identity_public_key(&self) -> Result<Option<[u8; 32]>, EcallError> {
        self.with_state(|state| Ok(state.as_ref().map(|s| *s.endpoint.identity().public_key())))
    }

    /// `enclave_create_report`: creates the identity key and the application
    /// on first use, then produces evidence committing to the key.
    ///
    /// Idempotent with respect to the key: every call reports the same
    /// `ek_pub`, so a host cannot obtain reports for two different keys
    /// from one instance.
    pub fn create_report<T>(
        &self,
        attester: &mut T,
        rng: &mut impl Rng,
    ) -> Result<Report, EcallError>
    where
        T: Attester<Evidence = Report>,
        T::Error: Into<SgxStatus>,
    {
        self.with_state(|state| {
            let state = match state {
                Some(state) => state,
                None => {
                    let identity = IdentityKey::generate(rng).map_err(EcallError::Rng)?;
                    let endpoint = EnclaveEndpoint::new(identity);
                    state.insert(State {
                        endpoint,
                        app: A::init(),
                    })
                }
            };
            let report_data = state.endpoint.identity().report_data();
            let report = attester
                .attest(&report_data)
                .map_err(|e| EcallError::Attestation(e.into()))?;
            let body = report.body();
            if body.report_data() != report_data {
                return Err(EcallError::Attestation(SgxStatus::UNEXPECTED));
            }
            state.endpoint.set_report_body(body);
            Ok(report)
        })
    }

    /// `enclave_message`: runs one protocol step and returns the reply
    /// payload (at most [`MAX_PAYLOAD`] bytes).
    pub fn message(&self, input: &[u8], rng: &mut impl Rng) -> Result<Vec<u8>, EcallError> {
        if input.len() > MAX_PAYLOAD {
            return Err(EcallError::InvalidParameter);
        }
        self.with_state(|state| {
            let State { endpoint, app } = state.as_mut().ok_or(EcallError::NotAttested)?;
            let context = SessionContext::new(*endpoint.identity().public_key());
            let reply = endpoint
                .handle(input, rng, |request, response| {
                    app.handle_with_context(&context, request, response)
                })
                .map_err(EcallError::Protocol)?;
            if reply.len() > MAX_PAYLOAD {
                // Unreachable: records are bounded by the record layer.
                return Err(EcallError::Protocol(EndpointError::App(AppError::new(
                    "reply exceeds the layer-1 payload limit",
                ))));
            }
            Ok(reply)
        })
    }
}

impl<A: EnclaveApp> Default for Runtime<A> {
    fn default() -> Self {
        Self::new()
    }
}

impl<A> fmt::Debug for Runtime<A> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Runtime")
            .field("busy", &self.busy.load(Ordering::Relaxed))
            .finish_non_exhaustive()
    }
}

/// Whether `[ptr, ptr + len)` is non-null and lies inside the enclave.
///
/// The edger8r bridge already copies `[in]`/`[out]` buffers into enclave
/// memory; this re-check keeps the glue safe if the EDL is ever changed to
/// `[user_check]`.
fn within_enclave<T>(ptr: *const T, len: usize) -> bool {
    // SAFETY: `sgx_is_within_enclave` only compares addresses.
    !ptr.is_null() && unsafe { ffi::sgx_is_within_enclave(ptr.cast(), len) } == 1
}

/// Glue for `enclave_create_report`.
///
/// # Safety
///
/// `p_qe3_target` must be null or point to a readable `sgx_target_info_t`,
/// and `p_report` null or point to a writable `sgx_report_t`, as the
/// edger8r bridge guarantees.
pub unsafe fn ecall_create_report<A: EnclaveApp>(
    runtime: &Runtime<A>,
    p_qe3_target: *const u8,
    p_report: *mut u8,
) -> u32 {
    if !within_enclave(p_qe3_target, TARGET_INFO_LEN) || !within_enclave(p_report, REPORT_LEN) {
        return SgxStatus::INVALID_PARAMETER.code();
    }
    // SAFETY: checked non-null and inside the enclave; the caller guarantees
    // the size. `[u8; N]` has alignment 1.
    let target_bytes = unsafe { &*p_qe3_target.cast::<[u8; TARGET_INFO_LEN]>() };
    let Ok(target) = TargetInfo::from_bytes(target_bytes) else {
        return SgxStatus::INVALID_PARAMETER.code();
    };
    match runtime.create_report(&mut SgxAttester::new(target), &mut SgxRng) {
        Ok(report) => {
            // SAFETY: checked non-null and inside the enclave; the caller
            // guarantees room for `REPORT_LEN` bytes.
            unsafe {
                p_report
                    .cast::<[u8; REPORT_LEN]>()
                    .write(*report.as_bytes())
            };
            SgxStatus::SUCCESS.code()
        }
        Err(e) => e.status().code(),
    }
}

/// Glue for `enclave_message`.
///
/// On success, writes the reply into `p_response` and its length into
/// `p_response_size`. On failure the size is 0. The unused rest of
/// `p_response` is always zeroed, so the 4096 bytes the bridge copies back
/// out contain nothing but the reply.
///
/// # Safety
///
/// `p_data` must be null or point to [`MAX_PAYLOAD`] readable bytes,
/// `p_response` null or point to [`MAX_PAYLOAD`] writable bytes, and
/// `p_response_size` null or point to a writable `u32`, as the edger8r
/// bridge guarantees.
pub unsafe fn ecall_message<A: EnclaveApp>(
    runtime: &Runtime<A>,
    p_data: *const u8,
    data_size: u32,
    p_response: *mut u8,
    p_response_size: *mut u32,
) -> u32 {
    if !within_enclave(p_response, MAX_PAYLOAD)
        || !within_enclave(p_response_size, core::mem::size_of::<u32>())
    {
        return SgxStatus::INVALID_PARAMETER.code();
    }
    // SAFETY: checked non-null and inside the enclave; the caller guarantees
    // MAX_PAYLOAD writable bytes, and the bridge's buffer is not aliased.
    let response = unsafe { core::slice::from_raw_parts_mut(p_response, MAX_PAYLOAD) };
    response.fill(0);
    // SAFETY: checked non-null and inside the enclave; unaligned write is
    // valid for any address.
    unsafe { p_response_size.write_unaligned(0) };

    let len = data_size as usize;
    if len > MAX_PAYLOAD || !within_enclave(p_data, MAX_PAYLOAD) {
        return SgxStatus::INVALID_PARAMETER.code();
    }
    // SAFETY: checked non-null and inside the enclave; the caller guarantees
    // MAX_PAYLOAD readable bytes, and `len <= MAX_PAYLOAD`.
    let input = unsafe { core::slice::from_raw_parts(p_data, len) };

    match runtime.message(input, &mut SgxRng) {
        Ok(reply) => {
            response[..reply.len()].copy_from_slice(&reply);
            // `reply.len() <= MAX_PAYLOAD` (checked in `Runtime::message`).
            // SAFETY: as above.
            unsafe { p_response_size.write_unaligned(reply.len() as u32) };
            SgxStatus::SUCCESS.code()
        }
        Err(e) => e.status().code(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use alloc::vec;
    use sgx_ra_core::attestation::{TcbStatus, VerifiedClaims};
    use sgx_ra_core::handshake::{ClientHandshake, Hello, HelloReply, MAX_RECORD_PLAINTEXT};
    use sgx_ra_core::record::Session;

    use crate::app::MAX_RESPONSE_LEN;

    /// Echoes, but rejects requests starting with `!` and answers `big`
    /// with an oversized response.
    #[derive(Debug)]
    struct TestApp {
        calls: usize,
    }

    impl EnclaveApp for TestApp {
        fn init() -> Self {
            Self { calls: 0 }
        }

        fn handle(&mut self, request: &[u8], response: &mut Vec<u8>) -> Result<(), AppError> {
            self.calls += 1;
            match request {
                [b'!', ..] => Err(AppError::new("rejected")),
                b"big" => {
                    response.resize(MAX_RESPONSE_LEN + 1, 0);
                    Ok(())
                }
                _ => {
                    response.extend_from_slice(request);
                    Ok(())
                }
            }
        }
    }

    const TARGET: [u8; TARGET_INFO_LEN] = [0u8; TARGET_INFO_LEN];

    /// Calls the ECALL glue like the edger8r bridge does.
    fn create_report(rt: &Runtime<TestApp>) -> (u32, [u8; REPORT_LEN]) {
        let mut report = [0u8; REPORT_LEN];
        // SAFETY: valid buffers of the documented sizes.
        let status = unsafe { ecall_create_report(rt, TARGET.as_ptr(), report.as_mut_ptr()) };
        (status, report)
    }

    fn message(rt: &Runtime<TestApp>, input: &[u8]) -> (u32, Vec<u8>, [u8; MAX_PAYLOAD]) {
        let mut data = [0u8; MAX_PAYLOAD];
        data[..input.len()].copy_from_slice(input);
        let mut response = [0xa5u8; MAX_PAYLOAD];
        let mut size = 0xdead_beef_u32;
        // SAFETY: valid buffers of the documented sizes.
        let status = unsafe {
            ecall_message(
                rt,
                data.as_ptr(),
                input.len() as u32,
                response.as_mut_ptr(),
                &mut size,
            )
        };
        (status, response[..size as usize].to_vec(), response)
    }

    /// Plays the client: quote verification is replaced by trusting the
    /// report body directly.
    fn handshake(rt: &Runtime<TestApp>) -> Session {
        let (status, report) = create_report(rt);
        assert_eq!(status, 0);
        let body = Report::from_bytes(&report).unwrap().body();
        let claims = VerifiedClaims::new(body, TcbStatus::UpToDate, Vec::new());
        let (client, hello) = ClientHandshake::start(&claims, &mut SgxRng).unwrap();
        let (status, reply, _) = message(rt, &hello.encode());
        assert_eq!(status, 0);
        client.finish(&HelloReply::decode(&reply).unwrap()).unwrap()
    }

    #[test]
    fn message_before_report_is_rejected() {
        let rt = Runtime::<TestApp>::new();
        let (status, reply, raw) = message(&rt, &[1, 1]);
        assert_eq!(status, SgxStatus::INVALID_STATE.code());
        assert!(reply.is_empty());
        assert_eq!(raw, [0u8; MAX_PAYLOAD], "response buffer must be wiped");
        assert!(!rt.is_initialized().unwrap());
    }

    #[test]
    fn report_commits_to_a_stable_identity_key() {
        let rt = Runtime::<TestApp>::new();
        let (s1, r1) = create_report(&rt);
        let (s2, r2) = create_report(&rt);
        assert_eq!((s1, s2), (0, 0));
        let ek_pub = rt.identity_public_key().unwrap().unwrap();
        let expected = sgx_ra_core::binding::report_data_for(&ek_pub);
        for raw in [r1, r2] {
            assert_eq!(
                Report::from_bytes(&raw).unwrap().body().report_data(),
                expected
            );
        }
    }

    #[test]
    fn rng_failure_leaves_runtime_uninitialised() {
        let rt = Runtime::<TestApp>::new();
        ffi::fake::FAIL_RAND.with(|f| f.set(Some(0x0001)));
        let (status, _) = create_report(&rt);
        assert_eq!(status, SgxStatus::UNEXPECTED.code());
        assert!(!rt.is_initialized().unwrap());
        assert_eq!(create_report(&rt).0, 0);
    }

    #[test]
    fn full_session_through_the_ecall_glue() {
        let rt = Runtime::<TestApp>::new();
        let mut session = handshake(&rt);

        for request in [
            &b"Hello, SGX server!"[..],
            &[0x42; MAX_RECORD_PLAINTEXT][..],
        ] {
            let record = session.seal(request).unwrap();
            let (status, reply, _) = message(&rt, &record);
            assert_eq!(status, 0);
            assert_eq!(session.open(&reply).unwrap(), request);
        }

        // A second HELLO ends the session; nothing works afterwards.
        let hello = Hello {
            client_public: [9; 32],
            client_nonce: [0; 32],
        };
        assert_eq!(
            message(&rt, &hello.encode()).0,
            SgxStatus::UNEXPECTED.code()
        );
        let record = session.seal(b"after").unwrap();
        assert_eq!(message(&rt, &record).0, SgxStatus::UNEXPECTED.code());
    }

    #[test]
    fn replayed_record_closes_the_session() {
        let rt = Runtime::<TestApp>::new();
        let mut session = handshake(&rt);
        let record = session.seal(b"once").unwrap();
        assert_eq!(message(&rt, &record).0, 0);
        assert_eq!(message(&rt, &record).0, SgxStatus::UNEXPECTED.code());
    }

    #[test]
    fn application_errors_close_the_session() {
        for request in [&b"!nope"[..], b"big"] {
            let rt = Runtime::<TestApp>::new();
            let mut session = handshake(&rt);
            let (status, reply, raw) = message(&rt, &session.seal(request).unwrap());
            assert_eq!(status, SgxStatus::UNEXPECTED.code());
            assert!(reply.is_empty());
            assert_eq!(raw, [0u8; MAX_PAYLOAD]);
            let next = session.seal(b"x").unwrap();
            assert_eq!(message(&rt, &next).0, SgxStatus::UNEXPECTED.code());
        }
    }

    #[test]
    fn rejects_bad_parameters() {
        let rt = Runtime::<TestApp>::new();
        let mut report = [0u8; REPORT_LEN];
        // SAFETY: null pointers are rejected before any access.
        unsafe {
            assert_eq!(
                ecall_create_report(&rt, core::ptr::null(), report.as_mut_ptr()),
                SgxStatus::INVALID_PARAMETER.code()
            );
            assert_eq!(
                ecall_create_report(&rt, TARGET.as_ptr(), core::ptr::null_mut()),
                SgxStatus::INVALID_PARAMETER.code()
            );
        }
        assert_eq!(create_report(&rt).0, 0);

        let data = vec![1u8; MAX_PAYLOAD];
        let mut response = [0u8; MAX_PAYLOAD];
        let mut size = 7u32;
        // SAFETY: valid buffers; oversize length and null pointers are
        // rejected before any read.
        unsafe {
            assert_eq!(
                ecall_message(
                    &rt,
                    data.as_ptr(),
                    MAX_PAYLOAD as u32 + 1,
                    response.as_mut_ptr(),
                    &mut size
                ),
                SgxStatus::INVALID_PARAMETER.code()
            );
            assert_eq!(size, 0);
            assert_eq!(
                ecall_message(&rt, core::ptr::null(), 2, response.as_mut_ptr(), &mut size),
                SgxStatus::INVALID_PARAMETER.code()
            );
            assert_eq!(
                ecall_message(
                    &rt,
                    data.as_ptr(),
                    2,
                    response.as_mut_ptr(),
                    core::ptr::null_mut()
                ),
                SgxStatus::INVALID_PARAMETER.code()
            );
        }
        // Parameter errors happen before the protocol: the instance can
        // still complete its handshake.
        let mut session = handshake(&rt);
        let (status, reply, _) = message(&rt, &session.seal(b"ok").unwrap());
        assert_eq!(status, 0);
        assert_eq!(session.open(&reply).unwrap(), b"ok");
    }

    #[test]
    fn empty_and_unknown_messages_fail() {
        let rt = Runtime::<TestApp>::new();
        assert_eq!(create_report(&rt).0, 0);
        assert_eq!(message(&rt, &[]).0, SgxStatus::UNEXPECTED.code());
        assert_eq!(message(&rt, &[0x7f, 0]).0, SgxStatus::UNEXPECTED.code());
        // A failed pre-handshake message does not burn the handshake.
        let mut session = handshake(&rt);
        let (status, reply, _) = message(&rt, &session.seal(b"still ok").unwrap());
        assert_eq!(status, 0);
        assert_eq!(session.open(&reply).unwrap(), b"still ok");
    }

    #[test]
    fn busy_runtime_refuses_reentry() {
        let rt = Runtime::<TestApp>::new();
        let nested = rt.with_state(|_| Ok(rt.is_initialized()));
        assert_eq!(nested.unwrap(), Err(EcallError::Busy));
        assert!(
            !rt.busy.load(Ordering::Relaxed),
            "guard must release the flag"
        );
    }
}
